}

import { GoogleGenAI, Type } from "@google/genai";
import { IntentType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = `
You are the brain of the OmniTick Universal Ticketing System. 
Your goal is to process user requests in any language and extract:
1. Intent (Booking, Checking Availability, Event Info, Cancellation, or General Query).
2. Entities (Event Name, Date, Location, Number of Tickets, Ticket Type).

Respond in JSON format only.

Output Schema Example:
{
  "reply": "Text response to user in their language",
  "intent": "BOOK_TICKET",
  "entities": {
    "event": "Concert",
    "date": "2024-12-25",
    "quantity": 2,
    "category": "Music"
  }
}
`;

export const processUserMessage = async (message: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: message,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            reply: { type: Type.STRING },
            intent: { 
              type: Type.STRING,
              enum: Object.values(IntentType)
            },
            entities: {
              type: Type.OBJECT,
              properties: {
                event: { type: Type.STRING },
                date: { type: Type.STRING },
                location: { type: Type.STRING },
                quantity: { type: Type.NUMBER },
                category: { type: Type.STRING }
              }
            }
          },
          required: ["reply", "intent"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Gemini processing error:", error);
    return {
      reply: "I'm having trouble processing that right now. Could you try again?",
      intent: IntentType.GENERAL_QUERY
    };
  }
};

/**
