import React, { useState, useRef, useEffect } from 'react';
import { Send, Mic, User, Bot, Sparkles, Loader2, Calendar, MapPin, Ticket as TicketIcon } from 'lucide-react';
import { ChatMessage, Event, IntentType, Ticket } from '../types';
import { processUserMessage } from '../services/gemini';
import { generateTicketHash, recordOnLedger } from '../utils/blockchain';

interface ChatInterfaceProps {
  events: Event[];
  onTicketPurchase: (ticket: Ticket) => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ events, onTicketPurchase }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I am your AI Ticketing Assistant. You can ask me to find events, book tickets, or check availability in any language. How can I help you today?",
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (text: string) => {
    if (!text.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      const result = await processUserMessage(text);

      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.reply,
        timestamp: new Date(),
        intent: result.intent,
        entities: result.entities
      };

      setMessages(prev => [...prev, assistantMsg]);

      // Logic for auto-booking or showing results based on Intent
      if (result.intent === IntentType.BOOK_TICKET && result.entities?.event) {
        handleAutoBooking(result.entities);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAutoBooking = (entities: any) => {
    // Search for closest match in our event list
    const foundEvent = events.find(e => 
      e.name.toLowerCase().includes(entities.event.toLowerCase()) ||
      entities.event.toLowerCase().includes(e.category.toLowerCase())
    );

    if (foundEvent) {
      // Simulate a small delay for "blockchain processing"
      setTimeout(() => {
        const ticket: Ticket = {
          id: `TKT-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
          eventName: foundEvent.name,
          date: foundEvent.date,
          location: foundEvent.location,
          price: foundEvent.basePrice * (entities.quantity || 1),
          type: 'General',
          status: 'active',
          blockchainHash: generateTicketHash(foundEvent),
          qrCode: `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${foundEvent.id}`
        };

        recordOnLedger({
          action: 'TICKET_ISSUANCE',
          ticketId: ticket.id,
          hash: ticket.blockchainHash,
          amount: ticket.price
        });

        onTicketPurchase(ticket);

        setMessages(prev => [...prev, {
          id: Date.now().toString(),
          role: 'assistant',
          content: `Success! I've booked your ticket for ${foundEvent.name}. It's secured on the blockchain and available in your wallet.`,
          timestamp: new Date()
        }]);
      }, 1500);
    }
  };

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Speech recognition not supported in this browser.");
      return;
    }

    const SpeechRecognition = (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      handleSend(transcript);
    };

    if (isListening) {
      recognition.stop();
    } else {
      recognition.start();
    }
  };

  return (
    <div className="max-w-4xl mx-auto h-[calc(100vh-160px)] flex flex-col">
      <div className="flex-1 overflow-y-auto space-y-6 pr-2 mb-4 custom-scrollbar">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
          >
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
              msg.role === 'user' ? 'bg-indigo-600' : 'bg-slate-800 border border-slate-700'
            }`}>
              {msg.role === 'user' ? <User size={20} /> : <Bot size={20} className="text-indigo-400" />}
            </div>

            <div className={`max-w-[80%] rounded-2xl p-4 ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-slate-800/50 border border-slate-800 text-slate-200 rounded-tl-none'
            }`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.content}</p>
              <div className={`mt-2 text-[10px] opacity-50 flex items-center gap-1 ${
                msg.role === 'user' ? 'justify-end' : 'justify-start'
              }`}>
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                {msg.role === 'assistant' && msg.intent && (
                  <span className="ml-2 px-1.5 py-0.5 rounded bg-indigo-500/20 text-indigo-300 font-mono">
                    {msg.intent}
                  </span>
                )}
              </div>
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="flex gap-4">
            <div className="w-10 h-10 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center">
              <Loader2 className="w-5 h-5 text-indigo-400 animate-spin" />
            </div>
            <div className="bg-slate-800/30 border border-slate-800 rounded-2xl rounded-tl-none p-4">
              <div className="flex gap-1">
                <span className="w-1.5 h-1.5 bg-slate-600 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                <span className="w-1.5 h-1.5 bg-slate-600 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                <span className="w-1.5 h-1.5 bg-slate-600 rounded-full animate-bounce"></span>
              </div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Area */}
      <div className="glass-panel rounded-2xl p-2 flex items-center gap-2">
        <button 
          onClick={toggleVoice}
          className={`p-3 rounded-xl transition-colors ${
            isListening ? 'bg-red-500/20 text-red-400 animate-pulse' : 'hover:bg-slate-800 text-slate-400'
          }`}
        >
          <Mic size={20} />
        </button>
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend(input)}
          placeholder="Ask anything... (e.g., 'Book 2 tickets for the Music Fest')"
          className="flex-1 bg-transparent border-none focus:ring-0 text-slate-100 placeholder:text-slate-500 py-3"
        />
        <button 
          onClick={() => handleSend(input)}
          disabled={!input.trim() || isProcessing}
          className="p-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Send size={20} />
        </button>
      </div>

      <div className="flex items-center justify-center gap-4 mt-4 text-[11px] text-slate-500 font-medium">
        <span className="flex items-center gap-1"><Sparkles size={12} className="text-amber-500" /> NLP Logic Enabled</span>
        <span className="flex items-center gap-1"><ShieldCheck size={12} className="text-blue-500" /> Blockchain Secured</span>
        <span className="flex items-center gap-1"><MapPin size={12} className="text-emerald-500" /> Global Search</span>
      </div>
    </div>
  );
};

export default ChatInterface;

