import React, { useState, useRef, useEffect } from 'react';
import { Send, Mic, User, Bot, Sparkles, Loader2, Calendar, MapPin, Ticket as TicketIcon, ShieldCheck, X, Zap } from 'lucide-react';
import { ChatMessage, Event, IntentType, Ticket } from '../types';
import { processUserMessage } from '../services/gemini';
import { generateTicketHash, recordOnLedger } from '../utils/blockchain';

interface ChatInterfaceProps {
  events: Event[];
  onTicketPurchase: (ticket: Ticket) => void;
  initialPrompt?: string | null;
  onPromptHandled?: () => void;
}

const QUICK_PROMPTS = [
  "What's happening this weekend?",
  "Recommend a tech event",
  "How do blockchain tickets work?",
  "Book a ticket for the Music Fest"
];

const ChatInterface: React.FC<ChatInterfaceProps> = ({ events, onTicketPurchase, initialPrompt, onPromptHandled }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Welcome back! I'm your OmniTick AI Concierge. I can find events, handle secure blockchain bookings, and answer your questions in any language. What's on your mind today?",
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    if (initialPrompt) {
      handleSend(initialPrompt);
      onPromptHandled?.();
    }
  }, [initialPrompt]);

  const handleSend = async (text: string) => {
    if (!text.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsProcessing(true);

    try {
      const result = await processUserMessage(text);

      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.reply,
        timestamp: new Date(),
        intent: result.intent,
        entities: result.entities
      };

      setMessages(prev => [...prev, assistantMsg]);

      if (result.intent === IntentType.BOOK_TICKET && result.entities?.event) {
        handleAutoBooking(result.entities);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAutoBooking = (entities: any) => {
    const foundEvent = events.find(e => 
      e.name.toLowerCase().includes(entities.event.toLowerCase()) ||
      entities.event.toLowerCase().includes(e.category.toLowerCase())
    );

    if (foundEvent) {
      setTimeout(() => {
        const ticket: Ticket = {
          id: `TKT-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
          eventName: foundEvent.name,
          date: foundEvent.date,
          location: foundEvent.location,
          price: foundEvent.basePrice * (entities.quantity || 1),
          type: 'General',
          status: 'active',
          blockchainHash: generateTicketHash(foundEvent),
          qrCode: `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${foundEvent.id}`
        };

        recordOnLedger({
          action: 'TICKET_ISSUANCE',
          ticketId: ticket.id,
          hash: ticket.blockchainHash,
          amount: ticket.price
        });

        onTicketPurchase(ticket);

        setMessages(prev => [...prev, {
          id: Date.now().toString(),
          role: 'assistant',
          content: `Confirming your reservation for ${foundEvent.name}. 🎫\n\nI've generated a unique NFT-based pass for you. Your transaction is finalized on the ledger at ${ticket.blockchainHash.substring(0, 10)}...`,
          timestamp: new Date()
        }]);
      }, 1500);
    }
  };

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Speech recognition not supported in this browser.");
      return;
    }
    const SpeechRecognition = (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => handleSend(event.results[0][0].transcript);
    isListening ? recognition.stop() : recognition.start();
  };

  return (
    <div className="max-w-4xl mx-auto h-full flex flex-col">
      {/* Messages */}
      <div className="flex-1 overflow-y-auto space-y-6 px-4 py-6 scrollbar-hide">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex gap-4 animate-in slide-in-from-bottom-2 duration-300 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
          >
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-lg ${
              msg.role === 'user' ? 'bg-indigo-600' : 'bg-slate-800 border border-slate-700'
            }`}>
              {msg.role === 'user' ? <User size={20} /> : <Bot size={20} className="text-indigo-400" />}
            </div>

            <div className={`max-w-[85%] rounded-[1.5rem] p-5 ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none shadow-xl shadow-indigo-900/10' 
                : 'bg-slate-800/60 backdrop-blur-md border border-slate-700/50 text-slate-100 rounded-tl-none'
            }`}>
              <p className="text-[15px] leading-relaxed whitespace-pre-wrap">{msg.content}</p>
              <div className={`mt-3 pt-2 border-t border-white/10 text-[10px] opacity-60 flex items-center gap-2 ${
                msg.role === 'user' ? 'justify-end' : 'justify-start'
              }`}>
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                {msg.role === 'assistant' && msg.intent && (
                  <span className="px-1.5 py-0.5 rounded bg-indigo-400/20 text-indigo-300 font-mono font-bold tracking-tight">
                    {msg.intent}
                  </span>
                )}
              </div>
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="flex gap-4 animate-pulse">
            <div className="w-10 h-10 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center">
              <Loader2 className="w-5 h-5 text-indigo-400 animate-spin" />
            </div>
            <div className="bg-slate-800/30 border border-slate-800 rounded-[1.5rem] rounded-tl-none p-5 flex items-center">
              <span className="text-sm text-slate-500 font-medium italic">Consulting ML engine...</span>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Section */}
      <div className="p-6 bg-[#020617]/40 backdrop-blur-xl border-t border-slate-800/50">
        {/* Quick Prompts */}
        <div className="flex gap-2 mb-4 overflow-x-auto pb-2 no-scrollbar">
          {QUICK_PROMPTS.map(p => (
            <button 
              key={p}
              onClick={() => handleSend(p)}
              className="px-4 py-2 rounded-xl bg-slate-900 border border-slate-800 text-xs font-bold text-slate-400 hover:text-white hover:border-indigo-500/50 hover:bg-slate-800 transition-all whitespace-nowrap flex items-center gap-2"
            >
              <Zap size={12} className="text-indigo-500" /> {p}
            </button>
          ))}
        </div>

        <div className="relative flex items-center gap-3">
          <div className="flex-1 relative flex items-center bg-slate-900/80 border border-slate-800 rounded-2xl focus-within:border-indigo-500/50 focus-within:ring-4 focus-within:ring-indigo-500/5 transition-all">
            <button 
              onClick={toggleVoice}
              className={`ml-2 p-3 rounded-xl transition-all ${
                isListening ? 'bg-red-500/20 text-red-400 animate-pulse' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <Mic size={22} />
            </button>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend(input)}
              placeholder="Ask me to book, find, or cancel anything..."
              className="flex-1 bg-transparent border-none focus:ring-0 text-slate-100 placeholder:text-slate-600 py-4 px-3 text-sm font-medium"
            />
          </div>
          <button 
            onClick={() => handleSend(input)}
            disabled={!input.trim() || isProcessing}
            className="p-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl transition-all active:scale-95 disabled:opacity-30 disabled:grayscale shadow-lg shadow-indigo-600/20"
          >
            <Send size={22} />
          </button>
        </div>

        <div className="mt-4 flex items-center justify-center gap-6">
          <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-sm shadow-emerald-500" />
            AI Online
          </div>
          <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
            <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shadow-sm shadow-blue-500" />
            Blockchain Linked
          </div>
        </div>
      </div>
    </div>
  );
};

