import { GoogleGenAI, Type } from "@google/genai";
import { IntentType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are the OmniTick Concierge, an advanced AI designed to make event ticketing effortless and secure. 
Your tone is professional, enthusiastic, and helpful. You speak any language fluently.

CORE TASKS:
1. Process user requests (e.g., booking, searching, asking about events).
2. Extract intent and entities accurately.
3. Provide a warm, helpful response that confirms you understood the user's specific request.

If a user wants to book, encourage them by highlighting why the event is great or noting that demand is high (ML insight).

RESPOND IN JSON ONLY:
{
  "reply": "Your conversational response here",
  "intent": "BOOK_TICKET" | "CHECK_AVAILABILITY" | "EVENT_INFO" | "CANCEL_BOOKING" | "GENERAL_QUERY",
  "entities": {
    "event": "Event Name",
    "date": "Date if specified",
    "quantity": 1,
    "category": "Music/Tech/etc"
  }
}
`;

export const processUserMessage = async (message: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: message,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            reply: { type: Type.STRING },
            intent: { 
              type: Type.STRING,
              enum: Object.values(IntentType)
            },
            entities: {
              type: Type.OBJECT,
              properties: {
                event: { type: Type.STRING },
                date: { type: Type.STRING },
                location: { type: Type.STRING },
                quantity: { type: Type.NUMBER },
                category: { type: Type.STRING }
              }
            }
          },
          required: ["reply", "intent"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Gemini processing error:", error);
    return {
      reply: "I'm having a brief connection issue with our ticketing nodes. Please try again in a moment!",
      intent: IntentType.GENERAL_QUERY
    };
  }
};

