              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600 group-focus-within:text-orange-500 transition-colors" />
                <input
                  type="email"
                  required
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full pl-12 pr-4 py-4 bg-slate-950/50 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500/50 outline-none text-slate-100 transition-all text-sm font-medium"
                  placeholder="arjun@omnitick.in"
                />
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between items-center ml-1">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">Password</label>
                {isLogin && (
                  <button type="button" className="text-[10px] text-orange-400 font-bold hover:text-orange-300">Forgot Password?</button>
                )}
              </div>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600 group-focus-within:text-orange-500 transition-colors" />
                <input
                  type="password"
                  required
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  className="w-full pl-12 pr-4 py-4 bg-slate-950/50 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500/50 outline-none text-slate-100 transition-all text-sm font-medium"
                  placeholder="••••••••"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-4 bg-orange-600 hover:bg-orange-500 text-white font-bold rounded-2xl transition-all shadow-xl shadow-orange-900/20 active:scale-95 flex items-center justify-center gap-2 group disabled:opacity-70"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  {isLogin ? 'Sign In' : 'Create Account'}
                  <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 flex items-center gap-4">
            <div className="h-px bg-slate-800 flex-1" />
            <span className="text-[10px] text-slate-600 font-black uppercase tracking-widest">Or Continue with</span>
            <div className="h-px bg-slate-800 flex-1" />
          </div>

          <div className="mt-6 grid grid-cols-2 gap-4">
            <button className="flex items-center justify-center gap-2 py-3.5 bg-slate-950/50 border border-slate-800 rounded-2xl text-xs font-bold text-slate-400 hover:text-white hover:bg-slate-900 transition-all">
              <Chrome size={16} /> Google
            </button>
            <button className="flex items-center justify-center gap-2 py-3.5 bg-slate-950/50 border border-slate-800 rounded-2xl text-xs font-bold text-slate-400 hover:text-white hover:bg-slate-900 transition-all">
              <Github size={16} /> GitHub
            </button>
          </div>
        </div>

        <div className="mt-8 flex items-center justify-center gap-6">
          <div className="flex items-center gap-2 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
            Blockchain Active
          </div>
          <div className="flex items-center gap-2 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
            <Sparkles size={12} className="text-orange-500" />
            AI Protection
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  MessageSquare, 
  Ticket as TicketIcon, 
  ShieldCheck, 
  Activity,
  Menu,
  Compass,
  Bell,
  Sparkles,
  LogOut
} from 'lucide-react';
import ChatInterface from './components/ChatInterface';
import Dashboard from './components/Dashboard';
import TicketWallet from './components/TicketWallet';
import Ledger from './components/Ledger';
import EventExplorer from './components/EventExplorer';
import AuthPage from './components/AuthPage';
import { Event, Ticket, User } from './types';

const INITIAL_EVENTS: Event[] = [
  { id: '1', name: 'IPL 2025: MI vs CSK', date: '2025-04-15', location: 'Wankhede Stadium, Mumbai', category: 'Sports', basePrice: 1500, available: 45, total: 33000, image: 'https://images.unsplash.com/photo-1531415074968-036ba1b575da?auto=format&fit=crop&q=80&w=800' },
  { id: '2', name: 'Sunburn Festival Goa', date: '2025-12-28', location: 'Vagator, Goa', category: 'Music', basePrice: 4500, available: 120, total: 50000, image: 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&q=80&w=800' },
  { id: '3', name: 'India Art Fair 2025', date: '2025-02-01', location: 'NSIC Grounds, New Delhi', category: 'Expo', basePrice: 700, available: 300, total: 5000, image: 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&q=80&w=800' },
  { id: '4', name: 'Bangalore Tech Summit', date: '2025-11-18', location: 'Bangalore Palace, Bengaluru', category: 'Conference', basePrice: 2500, available: 200, total: 2000, image: 'https://images.unsplash.com/photo-1540575861501-7ce0e1d1aa99?auto=format&fit=crop&q=80&w=800' },
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'explore' | 'chat' | 'dashboard' | 'wallet' | 'ledger'>('explore');
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [events] = useState<Event[]>(INITIAL_EVENTS);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [pendingPrompt, setPendingPrompt] = useState<string | null>(null);

  useEffect(() => {
    // Check for saved user
    const savedUser = localStorage.getItem('omni_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    // Check for saved tickets
    const savedTickets = localStorage.getItem('omni_tickets');
    if (savedTickets) setTickets(JSON.parse(savedTickets));
  }, []);

  const handleAuth = (userData: User) => {
    setUser(userData);
    localStorage.setItem('omni_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('omni_user');
  };

  const saveTicket = (ticket: Ticket) => {
    const updated = [...tickets, ticket];
    setTickets(updated);
    localStorage.setItem('omni_tickets', JSON.stringify(updated));
  };

  const handleEventClick = (eventName: string) => {
    setPendingPrompt(`I'd like to book a ticket for ${eventName}.`);
    setActiveTab('chat');
  };

  if (!user) {
    return <AuthPage onAuth={handleAuth} />;
  }

  const navItems = [
    { id: 'explore', label: 'Explore', icon: Compass },
    { id: 'chat', label: 'AI Concierge', icon: MessageSquare },
    { id: 'dashboard', label: 'My Insights', icon: LayoutDashboard },
    { id: 'wallet', label: 'My Tickets', icon: TicketIcon },
    { id: 'ledger', label: 'Trust Ledger', icon: ShieldCheck },
  ];

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 overflow-hidden font-inter">
      {/* Mobile Menu Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed md:relative z-50 h-full w-72 bg-[#0b0f1a] border-r border-slate-800/50 transition-all duration-300
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
        <div className="p-8 flex flex-col h-full">
          <div className="flex items-center gap-3 mb-12">
            <div className="p-2.5 bg-gradient-to-br from-orange-500 to-green-600 rounded-xl shadow-lg shadow-orange-500/20">
              <TicketIcon className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">OmniTick</h1>
              <span className="text-[10px] text-orange-400 font-mono tracking-widest uppercase">India's Smart Pass</span>
            </div>
          </div>

          <nav className="space-y-1.5 flex-1">
            {navItems.map(item => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id as any);
                  setIsSidebarOpen(false);
                }}
                className={`w-full flex items-center gap-3.5 px-5 py-3.5 rounded-2xl transition-all duration-200 group ${
                  activeTab === item.id 
                    ? 'bg-orange-600/10 text-orange-400 border border-orange-500/20' 
                    : 'text-slate-500 hover:bg-slate-800/40 hover:text-slate-200'
                }`}
              >
                <item.icon className={`w-5 h-5 transition-transform group-hover:scale-110 ${activeTab === item.id ? 'text-orange-400' : ''}`} />
                <span className="font-semibold text-sm">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="mt-auto pt-8 border-t border-slate-800/50 space-y-4">
            <div className="flex items-center gap-4 p-4 rounded-2xl bg-orange-500/5 border border-orange-500/10">
              <div className="relative">
                <img 
                  src={user.avatar} 
                  alt={user.name} 
                  className="w-10 h-10 rounded-full border-2 border-orange-500 shadow-md"
                />
                <div className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 border-2 border-[#0b0f1a]" />
              </div>
              <div className="flex-1 overflow-hidden">
                <p className="text-sm font-bold text-slate-200 truncate">{user.name}</p>
                <p className="text-[10px] text-slate-500 font-mono">Premium Account</p>
              </div>
            </div>

            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3.5 px-5 py-3.5 rounded-2xl text-slate-500 hover:bg-red-500/10 hover:text-red-400 transition-all group"
            >
              <LogOut className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
              <span className="font-semibold text-sm">Sign Out</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-[#020617] overflow-hidden relative">
        {/* Decorative elements */}
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-orange-600/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-green-600/10 rounded-full blur-[120px] pointer-events-none" />

        {/* Header */}
        <header className="h-20 flex items-center justify-between px-8 border-b border-slate-800/40 bg-[#020617]/40 backdrop-blur-xl sticky top-0 z-30">
          <div className="flex items-center gap-4">
            <button 
              className="md:hidden p-2 text-slate-400 hover:text-white transition-colors"
              onClick={() => setIsSidebarOpen(true)}
            >
              <Menu className="w-6 h-6" />
            </button>
            <h2 className="text-lg font-bold text-slate-100 capitalize">
              {navItems.find(i => i.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden lg:flex items-center gap-3 text-xs font-bold px-4 py-2 rounded-full bg-emerald-500/5 text-emerald-400 border border-emerald-500/20 shadow-sm shadow-emerald-500/5">
              <Activity className="w-3.5 h-3.5" />
              <span>Network: India-West-V1</span>
            </div>
            <button className="relative p-2.5 text-slate-400 hover:text-white transition-all bg-slate-900/50 border border-slate-800 rounded-xl">
              <Bell className="w-5 h-5" />
              <span className="absolute top-2 right-2 w-2 h-2 rounded-full bg-orange-500 border border-[#020617]" />
            </button>
          </div>
        </header>

        {/* Dynamic Viewport */}
        <div className="flex-1 overflow-y-auto p-6 md:p-10 relative">
          {activeTab === 'explore' && (
            <EventExplorer 
              events={events} 
              onEventClick={handleEventClick} 
            />
          )}
          {activeTab === 'chat' && (
            <ChatInterface 
              events={events} 
              onTicketPurchase={saveTicket}
              initialPrompt={pendingPrompt}
              onPromptHandled={() => setPendingPrompt(null)}
            />
          )}
          {activeTab === 'dashboard' && <Dashboard />}
          {activeTab === 'wallet' && <TicketWallet tickets={tickets} />}
          {activeTab === 'ledger' && <Ledger />}
        </div>
      </main>
    </div>
  );
};

export default App;
